package arrays_methods.assigment_problems;

import java.util.*; public class FantasyLeagueAutoDraft {static class Player implements Comparable<Player>{String name;int matchesPlayed;double battingAverage;boolean injured;Player(String n,int m,double a,boolean i){name=n;matchesPlayed=m;battingAverage=a;injured=i;}static boolean isDraftable(int m){return m>=10;}static boolean isDraftable(int m,boolean injured){return m>=5&&!injured;}public int compareTo(Player p){return Double.compare(p.battingAverage,battingAverage);}}static String draftAndRank(Player[] players){List<Player> list=new ArrayList<>();for(Player p:players)if(Player.isDraftable(p.matchesPlayed)||Player.isDraftable(p.matchesPlayed,p.injured))list.add(p);Player[] a=list.toArray(new Player[0]);Arrays.sort(a);StringBuilder s=new StringBuilder();for(int i=0;i<a.length;i++){if(i>0)s.append(" | ");s.append(i+1).append(". ").append(a[i].name);}return s.toString();}public static void main(String[] x){System.out.println(draftAndRank(new Player[]{new Player("Virat",15,48,false),new Player("Rahul",7,55,false),new Player("Sameer",3,60,false),new Player("Dev",12,20,true)}));}}
